// ============================================================
// BACKEND — Application Configuration
// ============================================================
// All credentials and settings are read from environment
// variables defined in the `.env` file at the project root.
//
// Each value has a hard-coded fallback so the app still runs
// if the .env file is missing (e.g. a fresh clone, or a host
// where env vars weren't configured yet).
//
// To change a value: edit `.env` — do NOT edit this file.
// ============================================================

/**
 * Safely read a Vite env variable with a fallback.
 * `import.meta.env` is replaced at build time by Vite.
 */
function env(key: keyof ImportMetaEnv, fallback: string): string {
  try {
    const value = import.meta.env?.[key];
    // Ignore empty strings and unresolved placeholders
    if (typeof value === 'string' && value.trim() !== '') {
      return value.trim();
    }
  } catch {
    /* import.meta.env unavailable — fall through to default */
  }
  return fallback;
}

